#!/usr/bin/env bun
import { fileURLToPath } from "node:url"

import { runProcess } from "./entry.ts"
import { RuntimeInfo } from "./runtime-info.ts"

// The entry point from source (`bun src/bin.ts`). The compiled binary has its
// own, generated by `scripts/build.ts`.

runProcess({
  runtimeInfo: RuntimeInfo.layerProcess,
  // argv[1] is this script.
  self: { command: process.execPath, args: [process.argv[1] ?? fileURLToPath(import.meta.url)] },
  // From source, the daemon serves the web client's build directory.
  dashboard: {
    _tag: "Directories",
    dirs: [fileURLToPath(new URL("../../web/dist", import.meta.url))],
  },
})
